var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    app.UseDeveloperExceptionPage(); // detailed stack traces — never in Production
    app.UseSwagger();
    app.UseSwaggerUI();
}
else
{
    app.UseExceptionHandler("/error"); // generic Problem Details response
    app.UseHsts();
}

app.MapControllers();
app.Run();

var builder = WebApplication.CreateBuilder(args);
var startupTimer = Stopwatch.StartNew();

builder.Services.AddControllers();
builder.Services.AddSingleton<IConnectionMultiplexer>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    return ConnectionMultiplexer.Connect(config["Redis:Connection"]!);
});

var app = builder.Build();

var lifetime = app.Services.GetRequiredService<IHostApplicationLifetime>();
lifetime.ApplicationStarted.Register(() =>
{
    startupTimer.Stop();
    app.Logger.LogInformation("Startup completed in {Ms}ms", startupTimer.ElapsedMilliseconds);
});

app.MapGet("/health", () => Results.Ok());
app.Run();
